/**
 * Fetching one list of repeaters from a declared source, when a person asks.
 *
 * One request, to the address the source names and to no other host (a redirect to
 * another host is refused, not followed), through the guarded HTTP client. The answer
 * is capped in size while it is read and given a limit of time. What comes back is
 * somebody else's file: it is held as text and read by the importer, which checks every
 * value; nothing in it is run or shown as a page.
 *
 * The file is generated by its publisher whenever it is asked for, so there is no
 * checksum to hold it to, as there is for a catalogue download. What stands in for one
 * is the importer's validation and its caps, and the preview a person sees before
 * anything is kept.
 *
 * A source is left alone between requests for as long as it asks (its crawl delay), and
 * never less than `MIN_WAIT_SECONDS`. If it says it is busy, or tells a client to come
 * back later, it is not asked again until then. Outpost does not answer a check that
 * its visitor is a browser, send a cookie, sign in, or try another address: a source
 * that wants any of those is one to download from by hand.
 */
import { MAX_REPEATER_FILE_BYTES } from "@outpost/shared";
import { AppError, classifyNetworkError } from "../../core/errors.ts";
import { BlockedAddressError, type HttpClient } from "../../core/http.ts";
import type { RepeaterSource } from "./sources.ts";

/** How long Outpost waits for the whole file. */
export const FETCH_TIMEOUT_MS = 120_000;
/** After a source says it is busy without saying for how long, it is not asked again for this long. */
export const BUSY_PAUSE_MS = 5 * 60_000;
/** The longest a source can put Outpost off for. Beyond it, the person is told to try another day. */
const LONGEST_PAUSE_MS = 24 * 3_600_000;

export interface FetchedList {
  text: string;
  /** The address that answered. */
  url: string;
  sizeBytes: number;
  /** When the publisher says the file last changed, if it says, as milliseconds. */
  lastModified: number | null;
  /** A name for the file, from its address. */
  fileName: string;
}

export interface RepeaterFetchClient {
  get(source: RepeaterSource, options?: { signal?: AbortSignal }): Promise<FetchedList>;
  /** Seconds until this source's host may be asked again; 0 when it may be asked now. */
  waitFor(source: RepeaterSource): number;
}

async function readCapped(response: { body: AsyncIterable<Uint8Array> | null }, maxBytes: number): Promise<Buffer | null> {
  const chunks: Uint8Array[] = [];
  let size = 0;
  if (!response.body) return Buffer.alloc(0);
  for await (const chunk of response.body) {
    size += chunk.byteLength;
    if (size > maxBytes) return null;
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}

/** "Retry-After: 120" or a date, as milliseconds from now. Null when there is none or it cannot be read. */
function retryAfterMs(value: string | null, now: number): number | null {
  if (!value) return null;
  if (/^\d{1,7}$/.test(value.trim())) return Number(value.trim()) * 1000;
  const at = Date.parse(value);
  return Number.isNaN(at) ? null : Math.max(0, at - now);
}

const seconds = (ms: number) => {
  const count = Math.ceil(ms / 1000);
  if (count < 120) return `${count} second${count === 1 ? "" : "s"}`;
  if (count < 7200) return `${Math.ceil(count / 60)} minutes`;
  return `${Math.ceil(count / 3600)} hours`;
};

/**
 * The last part of an address's path, for a file name. An escape that is not UTF-8
 * ("r%E9p.csv", an é written as one Latin-1 byte) cannot be decoded; the name is then
 * used as it is written, and the file that was fetched is not thrown away over its name.
 */
function lastSegment(url: string): string {
  const written = new URL(url).pathname.split("/").filter(Boolean).at(-1) ?? "";
  try {
    return decodeURIComponent(written);
  } catch {
    return written;
  }
}

export function createRepeaterFetchClient(
  http: HttpClient,
  options: { userAgent: string; now?: () => number; timeoutMs?: number; maxBytes?: number },
): RepeaterFetchClient {
  const now = options.now ?? Date.now;
  const timeoutMs = options.timeoutMs ?? FETCH_TIMEOUT_MS;
  const maxBytes = options.maxBytes ?? MAX_REPEATER_FILE_BYTES;
  /** By host: when it may next be asked. */
  const notBefore = new Map<string, number>();
  let fetching = false;

  const byHand = (source: RepeaterSource) => `Download the file yourself from ${source.pageUrl} and bring it in with “Import a list”.`;

  return {
    waitFor(source) {
      if (!source.fetch) return 0;
      return Math.max(0, Math.ceil(((notBefore.get(source.fetch.host) ?? 0) - now()) / 1000));
    },

    async get(source, ask = {}) {
      if (source.kind !== "fetch" || !source.fetch || !source.allowHost) {
        throw new AppError("bad_request", `Outpost does not fetch “${source.name}”. ${byHand(source)}`);
      }
      const host = source.fetch.host;
      const wait = (notBefore.get(host) ?? 0) - now();
      if (wait > 0) {
        throw new AppError(
          "conflict",
          `${host} was asked a moment ago. Outpost leaves it alone between requests: try again in ${seconds(wait)}.`,
          {
            retryInSeconds: Math.ceil(wait / 1000),
          },
        );
      }
      if (fetching) throw new AppError("conflict", "Another list is being fetched. Wait for it to finish, then try again.");
      fetching = true;
      // Counted from when the request is sent, whatever becomes of it.
      notBefore.set(host, now() + source.fetch.waitSeconds * 1000);
      const putOff = (ms: number) => notBefore.set(host, Math.max(notBefore.get(host) ?? 0, now() + Math.min(ms, LONGEST_PAUSE_MS)));
      const timeout = AbortSignal.timeout(timeoutMs);
      const signal = ask.signal ? AbortSignal.any([ask.signal, timeout]) : timeout;
      try {
        const { response, url } = await http.fetch(source.fetch.url, {
          headers: { accept: "text/csv, application/json, text/plain;q=0.9, */*;q=0.1", "user-agent": options.userAgent },
          allowedHosts: [source.allowHost],
          everyHop: true,
          maxRedirects: 3,
          signal,
        });
        if (!response.ok) {
          await response.body?.cancel().catch(() => undefined);
          if (response.status === 429 || response.status === 503) {
            const pause = retryAfterMs(response.headers.get("retry-after"), now()) ?? BUSY_PAUSE_MS;
            putOff(pause);
            throw new AppError(
              "upstream",
              `${host} is busy and turned the request away (HTTP ${response.status}). Outpost will not ask it again for ${seconds(Math.min(pause, LONGEST_PAUSE_MS))}.`,
            );
          }
          if (response.status === 401 || response.status === 403) {
            putOff(BUSY_PAUSE_MS);
            throw new AppError(
              "upstream",
              `${host} refused to give the file to Outpost (HTTP ${response.status}). It may want a sign-in, or check that its visitor is a browser; Outpost does not get round either. ${byHand(source)}`,
            );
          }
          if (response.status === 404 || response.status === 410) {
            throw new AppError(
              "upstream",
              `The file is no longer at the address Outpost has for it (HTTP ${response.status}). ${byHand(source)}`,
            );
          }
          throw new AppError("upstream", `${host} could not give the file (HTTP ${response.status}). Try again later.`);
        }
        const type = (response.headers.get("content-type") ?? "").toLowerCase();
        const bytes = await readCapped(response as { body: AsyncIterable<Uint8Array> | null }, maxBytes);
        if (bytes === null) {
          throw new AppError(
            "too_large",
            `The file from ${host} is larger than ${Math.round(maxBytes / (1024 * 1024))} MB, which is more than Outpost reads as a list of repeaters. Nothing was kept.`,
          );
        }
        const text = bytes.toString("utf8");
        // A page in place of the file: a notice, a sign-in, or a check that the visitor is a browser.
        if (type.includes("text/html") || /^\s*<(!doctype|html|head|body)\b/i.test(text.slice(0, 400))) {
          putOff(BUSY_PAUSE_MS);
          throw new AppError(
            "upstream",
            `${host} answered with a web page in place of the file. It may be checking that its visitor is a browser, or may have moved the file; Outpost does not get round the first and will not guess at the second. ${byHand(source)}`,
          );
        }
        if (!text.trim()) throw new AppError("upstream", `${host} answered with an empty file. Try again later.`);
        const modified = Date.parse(response.headers.get("last-modified") ?? "");
        const sane = !Number.isNaN(modified) && modified <= now() + 86_400_000 && modified > Date.UTC(2000, 0, 1);
        const last = lastSegment(url).replace(/[^\w .()-]/g, "_");
        return {
          text,
          url,
          sizeBytes: bytes.length,
          lastModified: sane ? modified : null,
          fileName: (last || `${source.id}.txt`).slice(0, 120),
        };
      } catch (error) {
        if (error instanceof BlockedAddressError) {
          throw new AppError(
            "forbidden",
            `Outpost did not ask ${host} because it is on this computer or a private network. A source on your own network needs the server started with OUTPOST_ALLOW_PRIVATE_DOWNLOADS=true.`,
          );
        }
        if (error instanceof AppError) {
          // The first request goes to the source's own host, so this can only be a redirect to another.
          if (error.code === "forbidden") {
            throw new AppError(
              "upstream",
              `${host} sent Outpost on to another site for the file. Outpost fetches a list only from the host its source names. ${byHand(source)}`,
            );
          }
          throw error;
        }
        if (ask.signal?.aborted) throw new AppError("bad_request", "Fetching the list was cancelled.");
        const code = (error as { cause?: { code?: string } } | null)?.cause?.code;
        if (timeout.aborted || code === "UND_ERR_HEADERS_TIMEOUT" || code === "UND_ERR_BODY_TIMEOUT") {
          throw new AppError(
            "upstream",
            `${host} did not send the whole file within ${seconds(timeoutMs)}. Nothing was kept. Try again later.`,
          );
        }
        if (classifyNetworkError(error) === "offline") {
          throw new AppError(
            "offline",
            `Outpost could not reach ${host}. Getting a list needs an internet connection at the moment you ask; the repeaters already held do not.`,
          );
        }
        throw new AppError("upstream", `The connection to ${host} failed part of the way through. Nothing was kept. Try again later.`);
      } finally {
        fetching = false;
      }
    },
  };
}
